<?php

namespace Illuminate\Tests\Database;

use Illuminate\Database\Capsule\Manager as DB;
use Illuminate\Database\Eloquent\Model;
use PHPUnit\Framework\TestCase;

class ChaperonePluckReproTest extends TestCase
{
    protected function setUp(): void
    {
        $db = new DB;
        $db->addConnection(['driver' => 'sqlite', 'database' => ':memory:']);
        $db->bootEloquent();
        $db->setAsGlobal();

        $this->schema()->create('users', function ($table) {
            $table->increments('id');
        });
        $this->schema()->create('posts', function ($table) {
            $table->increments('id');
            $table->foreignId('user_id');
        });

        $user = ChaperonePluckUser::create();
        $user->posts()->createMany([[], []]);
    }

    protected function tearDown(): void
    {
        $this->schema()->drop('users');
        $this->schema()->drop('posts');
    }

    protected function schema()
    {
        return ChaperonePluckUser::getConnection()->getSchemaBuilder();
    }

    public function testPluckWithChaperoneDoesNotFail()
    {
        $user = ChaperonePluckUser::first();
        $ids = $user->posts()->pluck('id')->all();
        $this->assertSame([1, 2], $ids);

        $posts = $user->posts()->get();
        $this->assertTrue($posts[0]->relationLoaded('user'));
        $this->assertSame($user, $posts[0]->user);
    }
}

class ChaperonePluckUser extends Model
{
    protected $table = 'users';
    protected $guarded = [];

    public function posts()
    {
        return $this->hasMany(ChaperonePluckPost::class, 'user_id')->chaperone('user');
    }
}

